        .unwrap_or_else(|error| panic!("Wisp CLI should execute: {error}"))
}

fn json_output(output: &std::process::Output) -> Value {
    serde_json::from_slice(&output.stdout)
        .unwrap_or_else(|error| panic!("CLI stdout should be JSON: {error}"))
}

#[test]
fn validate_accepts_a_valid_candidate() {
    let output = command(&[
        "artifact".to_owned(),
        "validate".to_owned(),
        fixture("spec-valid.json").display().to_string(),
    ]);
    assert!(output.status.success());
    assert_eq!(
        json_output(&output),
        json!({"artifact_type":"spec@1", "id":"SPEC-001", "status":"validated"})
    );
}

#[test]
fn validate_rejects_schema_failures_as_json_errors() {
    for fixture_name in ["spec-unknown-property.json", "spec-missing-required.json"] {
        let output = command(&[
            "artifact".to_owned(),
            "validate".to_owned(),
            fixture(fixture_name).display().to_string(),
        ]);
        assert!(!output.status.success());
        assert_eq!(
            json_output(&output),
            json!({"code":"schema_violation", "status":"error"})
        );
    }
}

#[test]
fn validate_rejects_malformed_json_as_a_json_error() {
    let output = command(&[
        "artifact".to_owned(),
        "validate".to_owned(),
        fixture("spec-malformed.json").display().to_string(),
    ]);
    assert!(!output.status.success());
    assert_eq!(
        json_output(&output),
        json!({"code":"invalid_json", "status":"error"})
    );
}

#[test]
fn persist_get_and_status_use_the_canonical_path() {
    let workspace = tempdir().unwrap_or_else(|error| panic!("temp workspace: {error}"));
    let workspace = workspace.path().display().to_string();
    let persist = command(&[
        "artifact".to_owned(),
        "persist".to_owned(),
        fixture("spec-valid.json").display().to_string(),
        "--workspace".to_owned(),
        workspace.clone(),
    ]);
    assert!(persist.status.success());
    assert_eq!(json_output(&persist)["path"], "docs/specs/SPEC-001.json");

    let get = command(&[
        "artifact".to_owned(),
        "get".to_owned(),
        "SPEC-001".to_owned(),
        "--workspace".to_owned(),
        workspace.clone(),
    ]);
    assert!(get.status.success());
    assert_eq!(
